import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UXD-021 — /explore HUD: one fixed-width scale bar, a picker that stays on screen, pills for their owner, an aligned REFERENCES grid, Reset always in its slot","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-021-explore-hud-scale-bar-picker-pills-references.md","filePath":"uxs/decisions/UXD-021-explore-hud-scale-bar-picker-pills-references.md"}'),r={name:"uxs/decisions/UXD-021-explore-hud-scale-bar-picker-pills-references.md"};function d(i,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="uxd-021-—-explore-hud-one-fixed-width-scale-bar-a-picker-that-stays-on-screen-pills-for-their-owner-an-aligned-references-grid-reset-always-in-its-slot" tabindex="-1">UXD-021 — /explore HUD: one fixed-width scale bar, a picker that stays on screen, pills for their owner, an aligned REFERENCES grid, Reset always in its slot <a class="header-anchor" href="#uxd-021-—-explore-hud-one-fixed-width-scale-bar-a-picker-that-stays-on-screen-pills-for-their-owner-an-aligned-references-grid-reset-always-in-its-slot" aria-label="Permalink to &quot;UXD-021 — /explore HUD: one fixed-width scale bar, a picker that stays on screen, pills for their owner, an aligned REFERENCES grid, Reset always in its slot&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; the e2e run and the shots are the lead&#39;s to run, see Verification)</li><li><strong>Date</strong>: 2026-11-12 (proposed and decided)</li><li><strong>Decider</strong>: the operator, 2026-11-12 — every open question of <code>docs/wip/2026-11-12-slice-C3-brief.md</code> §11 approved as recommended</li><li><strong>Answers</strong>: E4, SS1, SS2, SS3 of the UX feedback plan; slice C3</li><li><strong>Builds on</strong>: <a href="./UXD-019-select-equals-focus">UXD-019</a> (C1: the four outer Resets, <code>selectedSmallBodyId</code>; C3 replaces &quot;the outer-scale Reset appears after a selection&quot; with &quot;Reset is always drawn&quot;), <a href="./UXD-014-one-chip-and-filter">UXD-014</a> / <a href="./UXD-015-flat-chip-row">UXD-015</a> (a HUD action that mounts and unmounts shifts the row: it is always rendered and disabled when inert), <a href="./UXD-018-panel-shell-and-actions">UXD-018</a> (the 400 px drawer the row clears), <a href="./UXD-017-one-index-on-every-scale">UXD-017</a> (the INDEX handle, and the ladder&#39;s z-index of 46), <a href="./UXD-002-type-scale-and-the-11px-floor">UXD-002</a> (11 px floor; the overlay&#39;s labels move from the canvas to DOM tokens), <a href="./UXD-020-explore-readability-pins-rings-labels">UXD-020</a> (pins and rings; the direction pills are not pin labels)</li><li><strong>Changes</strong>: <code>src/lib/universe/scale-bar.ts</code> and <code>src/lib/components/ScaleBar.svelte</code> (new, with the test), <code>scale-readout.ts</code> (<code>niceScaleBar</code> removed), <code>src/routes/explore/ScaleStrip.svelte</code>, <code>src/lib/surface-scene/SurfaceScene.svelte</code>, <code>SurfaceFlatPatch.svelte</code>, <code>src/lib/explore/format.ts</code> (<code>distanceWithUnit</code> knows <code>m</code>; <code>planetName</code>), <code>ExploreScalePicker.svelte</code>, <code>src/routes/explore/ScaleNav.svelte</code>, <code>+page.svelte</code> (<code>solarHasSelection</code>, <code>resetSolarView</code>, <code>scaleResetEnabled</code>, <code>panelCoverPx</code>), <code>explore-scene-host.ts</code> (the bar, <code>panelCoverPx</code>, the pills), <code>explore-solar-scene.ts</code>, <code>iconic-trajectory.ts</code>, <code>src/lib/explore/planet-sizes.ts</code> (new), <code>SizesCanvas.svelte</code>, <code>SizesOverlay.svelte</code>, <code>messages/{ar,ja,ko}.json</code>, <code>tests/e2e/explore-hud.spec.ts</code> (new), <code>tests/e2e/chip.spec.ts</code> (allow-list); <a href="./../UXS-014">UXS-014</a>, <a href="./../UXS-016">UXS-016</a>, <code>docs/concept/05_Design_System.md</code> (§5.15), <code>docs/uxs/IA.md</code>, <code>AGENTS.md</code>, <code>docs/adr/TA.md</code></li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The lower-right bar was a round-number length drawn at whatever pixel width that length had: 52 to 130 px as you zoomed, and the box around it resized with its text. The two Worlds bars did the same with their own code (63 to 157 px, 60 to 120 px). At the solar system the scale navigator is flush right and the picker&#39;s ladder was anchored left under its chip, so the ladder ran past the screen edge in all 14 locales (6 to 72 px by arithmetic). With any side panel open the navigator sat under the panel (z 30), so the user could not change scale. The Vega pill was an unexplained rounded border on the first screen. The REFERENCES overlay staggered two-line labels onto up to three extra rows under bodies 2 to 6 px wide, in English in every locale, and its &quot;diameters&quot; were the radii. Evidence: the brief&#39;s §0 to §3.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>One fixed-width scale bar.</strong> The bar is 120 px wide (64 px under 600 px wide), with end ticks, at every zoom; the value beside it follows the zoom, to three significant digits in the page locale (<code>1.37</code>, <code>13,7</code>, <code>137</code>), not a round number. One module (<code>scale-bar.ts</code>: <code>fixedScaleBar</code>, <code>scaleBarWidth</code>, <code>formatBarValue</code>, <code>worldsBarQuantity</code>) and one component (<code>ScaleBar.svelte</code>) serve the Explore strip and both Worlds bars; the unit comes from the existing ladders (<code>describeDistanceAu</code> for Explore; km from 1 km and metres below for the Worlds, through <code>distanceWithUnit</code>, no new key). The strip box is a fixed 232 px wide (190 px under 600 px, the bar&#39;s own breakpoint), so it no longer resizes with its text. Beside the bar the box cannot hold the longest label (232 - 24 padding and border - 120 bar - 7 gap = 81 px; de &quot;1.230 Lichtjahre&quot; is about 108 px), so in the strip the label sits under the bar (<code>ScaleBar</code> <code>stacked</code>): the box width stays fixed, the strip is one line taller, and the Worlds bars keep the label beside the bar. <code>niceScaleBar</code> and the two Worlds rounding blocks are deleted.</li><li><strong>The schematic scales draw no bar.</strong> Milky Way to Cosmic web are not to scale; they keep the schematic note and the Learn-more link. UXS-016&#39;s &quot;kpc scale bar&quot; line is corrected.</li><li><strong>The level picker&#39;s ladder stays on screen.</strong> <code>ExploreScalePicker</code> takes <code>align</code>; the scale navigator passes <code>right</code> at the solar system, where it is flush right, so the ladder opens leftward from the chip&#39;s right edge; <code>max-inline-size: calc(100vw - 16px)</code> caps its width and, when it opens, its position is clamped to [8 px, viewport - 8 px] from the chip&#39;s measured rect (a width cap alone left it 23 px past the right edge in <code>ar</code> at 393 px), in either direction. The offsets are physical (<code>left</code> / <code>right</code>), not logical: the navigator&#39;s flush-right is <code>right: 8px</code> in every direction, so in RTL a logical <code>end</code> would put the ladder past the edge it must avoid (in <code>ar</code> the picker is the rightmost item and Reset is to its left). At the other seven scales the navigator is flush left and the ladder keeps <code>left: 0</code>.</li><li><strong>The row clears a docked side panel.</strong> With a drawer docked at the right edge (desktop, touch landscape) the flush-right row sits left of it: its right offset is the drawer&#39;s width plus the 8 px gutter. The width is the measurement the panel-aware framing already makes each time a panel opens or closes (<code>panelCoverPx</code>, now published to the page as <code>bridge.panelCoverPx</code>), not a second measurement. The scale strip takes the same offset (right = 12 px + the cover): with a drawer docked it sits left of it, not under it. A bottom sheet (touch portrait) covers the scene and moves nothing. The z-index stays 8 / 46: raising it would cover the panel bar&#39;s Share and ×. The Explore HUD row (z 45, top left) takes the worlds&#39; &quot;stop before the panel&quot; rule (<code>hud-beside-panel</code>): its <code>max-width</code> stops 12 px before the navigator&#39;s measured left edge (cover + 8 + the navigator&#39;s width), so the row wraps there and the two rows never intersect.</li><li><strong>One RESET VIEW per scale, always rendered, disabled while inert.</strong> At the seven outer scales it is the navigator&#39;s, next to the picker: disabled while the scale has nothing to reset (the A4 disabled look), so the row never shifts when you select; it runs C1&#39;s functions, and the neighbourhood&#39;s is also enabled while the Sun is out of frame. At the solar system it is the HUD row&#39;s RESET VIEW at the top left (A5, UXD-015), enabled by a selection of any kind (<code>resetSolarView</code>); the navigator draws none there, so there are never two on screen.</li><li><strong>Direction pills show only for their owner.</strong> The pills are hidden at load. ʻOumuamua&#39;s &quot;← Vega&quot; shows while the body is hovered or selected; a heading craft&#39;s &quot;→ star&quot; shows while its path is highlighted (hover or selection, the same <code>setHighlight</code>). The arrows stay. A named star takes its name from the overlay the star panel reads (<code>getNamedStarI18n</code>: Vega is Wega in <code>de</code>, Вега in <code>ru</code>, ベガ in <code>ja</code>); a catalogue-only star (Gliese 445, Ross 248, Lambda Aquilae) keeps its data name. Four craft carry a heading star (New Horizons has none), so there are five pills, not six.</li><li><strong>The REFERENCES overlay is a canvas of bodies and a DOM grid of names.</strong> <code>SizesCanvas</code> draws only the eight bodies, true relative size, common baseline, size order (no labels, leader lines, header or source line). <code>SizesOverlay</code> lists them in a grid under it, in the same left-to-right order (eight columns on the 640 px card, 4 × 2 under 620 px): a swatch in the planet&#39;s colour, the name in the viewer&#39;s language (<code>planetName</code>, <code>lab_body_*</code>), the diameter in the page locale with <code>distanceWithUnit(…, &#39;km&#39;)</code>; the open planet&#39;s cell is marked; hover, focus or a tap on a cell rings its body in the canvas (a cell is a button, <code>.sizes-cell</code>, on the A4 allow-list). The heading (<code>sizes_header</code>) is above the canvas and the source line (<code>sizes_source</code>) under the grid. The listed diameters are the mean diameters of <code>planet-stats.ts</code> (the table the planet panel and the Tactical Scan read), so Mars, Jupiter and Saturn read the same everywhere (the old strings were the radii under a &quot;diameters&quot; heading). A name never breaks mid-word from 360 px up: the longest (nl MERCURIUS, 9 letters) is 9 x 6.73 = 60.6 px in Space Mono 11 px, 58.6 px with -0.02 em tracking, in a cell text box of 61 px (4 columns at 360 px) to 65 px (8 columns at the 620 px breakpoint, which replaces 560 px for that reason); under 360 px the word may break rather than overflow. A focused cell shows the chip focus outline (2 px <code>--color-focus</code>). Hand fixes in the three locales whose heading or source line was wrong or partial: <code>ar</code> (heading and source), <code>ja</code> (source said &quot;distance&quot;), <code>ko</code> (source said &quot;소스&quot;).</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>The bar&#39;s label reads a value like <code>13.7 AU</code> instead of <code>10 AU</code>, so the label changes with every wheel step (it re-renders per frame while zooming, a text node). A round number at a fixed width is no longer possible (stated in the brief&#39;s Q1). The Explore strip is 28 px narrower than its old maximum of 260 and, with the label under the bar, one line taller. At the solar system the navigator is one chip shorter (no Reset), which also removes the extra chip from the phone&#39;s top-right row. The drawer clearance (navigator, strip, HUD row) reads the measurement that is taken in the 400 ms after a panel opens, closes, or the window resizes. That measurement runs every frame while the drawer&#39;s 220 ms fly-in plays, so the cleared items follow the drawer&#39;s edge frame by frame during the fly-in and have no transition of their own (not a single move after the measure settles; a CSS transition on top of a per-frame value would lag it). Wherever the HUD row&#39;s <code>max-width</code> shrinks, the layer chips wrap onto another line sooner than before.</p><p>Follow-up (operator, 2026-11-12, iPhone): the strip&#39;s lifts are for the time dock, so they apply only at the solar system; at the other scales the strip sits at the bottom (12 px on touch, 46 px above the footer otherwise). The fixed 232 px box overlapped the dock&#39;s right end at 800 px wide, so the 104 px lift now starts under 900 px. On touch the time dock starts at the left edge: the desktop offset beside the REFERENCES card (hidden on touch) pushed it over the drawer&#39;s tab row in landscape; under 720 px the tabs are tighter so the dock and the three tabs share one line on a 667 px phone.</p><p>The touch top-left cluster (<code>hud-top-mobile</code>) takes the same clearance and wraps (2026-11-12: fr &quot;RÉINITIALISER LA VUE&quot; at 360 px ran under the picker; e2e at 360 px in fr, de, ru). Not covered: that cluster with a docked drawer on a touch landscape device (it the clearance includes the drawer cover, but no test runs it there); the orbit ruler (C4); the REFERENCES chip in the time dock (A4); the breadcrumb and picker redesign (C8); the encounter labels of the iconic paths (done in C7, <a href="./UXD-026-iconic-missions-legend-and-milestone-boxes">UXD-026</a>).</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Unit: <code>src/lib/universe/scale-bar.test.ts</code> (same width at five distances, three significant digits in <code>en-US</code>, <code>de</code> and <code>ru</code>, widths 120 and 64, the Worlds km and m split), <code>scale-readout.test.ts</code> (the <code>niceScaleBar</code> cases removed), <code>src/lib/explore/planet-sizes.test.ts</code> (eight planets in size order, every diameter equal to the planet-stats mean diameter, a name for each planet in all 14 locales of at most 9 letters, not English in the non-Latin locales), <code>src/lib/explore/format.test.ts</code> (<code>distanceWithUnit</code> for every unit incl. <code>m</code>, in <code>ru</code> and <code>ar</code> too). E2: <code>tests/e2e/explore-hud.spec.ts</code> on all three projects, nothing skipped (bar width and strip box at four wheel steps; the Worlds 3D and flat-patch bars; the ladder inside the viewport at 1100, 1280 and 1440 px in <code>en</code>, <code>de</code>, <code>ru</code>, <code>ar</code>; the picker is the hit target with <code>?id=mars</code> open and a rung changes scale; the ladder inside [8, viewport - 8] for <code>ru</code>, <code>fr</code>, <code>ar</code> at 393 and 360 px; the strip label inside the box in <code>en</code>, <code>de</code>, <code>hi</code>, <code>ar</code> at 1280, 700 and 390 px and the strip left of a docked panel; the HUD row and the navigator never intersect with a panel open at 1100 and 1280 px; exactly one Reset on screen per scale, in its slot at all eight scales; the pills; the overlay grid, <code>de</code>, <code>ru</code>, <code>ar</code>, <code>ja</code>). The slice&#39;s check script (<code>docs/wip/2026-11-12-slice-C3-brief.md</code> §6) prints <code>C3-CHECK violations: 0</code>.</p>',12)])])}const f=t(r,[["render",d]]);export{u as __pageData,f as default};
